export const UpdateStaffBody = zod.object({
  "action": zod.enum(['role', 'ban', 'password', 'unban']),
  "role": zod.enum(['admin', 'moderator', 'user']).optional(),
  "reason": zod.string().max(updateStaffBodyReasonMax).nullish(),
  "password": zod.string().min(updateStaffBodyPasswordMin).max(updateStaffBodyPasswordMax).nullish()
})

export const UpdateStaffResponse = zod.object({
  "id": zod.string(),
  "name": zod.string(),
  "email": zod.string().email(),
  "role": zod.enum(['admin', 'moderator', 'user']),
  "banned": zod.boolean()
})


